# Compute short‑term assets and liabilities

def get_short(df):
    assets = df.loc[df['item_label_norm'].str.contains('TÀI SẢN NGĂN HẠN|TÀI SẢN NGẮN HẠN', na=False), 'period_current'].sum()
    liabilities = df.loc[df['item_label_norm'].str.contains('Nợ ngắn hạn|Nợ ngắn hạn', na=False), 'period_current'].sum()
    return assets, liabilities

# Compute total assets and liabilities

def get_total_assets(df):
    return df.loc[df['item_label_norm'].str.contains('Tổng tài sản|Tài sản', na=False), 'period_current'].sum()

def get_total_liabilities(df):
    return df.loc[df['item_label_norm'].str.contains('Nộ phải trả|Nợ ngắn hạn|Nợ', na=False), 'period_current'].sum()

# Net income

def get_net_income(df):
    row = df.loc[df['item_label_norm'].str.contains('Lợi nhuận thuần trong năm|Lợi nhuận thuần', na=False)]
    return row['period_current'].iloc[0] if not row.empty else 0.0

